package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The settings kept per sheet, by key. A setting never set, or set blank, has no value. */
@Repository
public class SettingStore {

    public static final String CLERK_LIMIT = "clerk-limit";

    public static final String FLOOR = "floor";

    public static final String TERMS = "terms";

    /** The terms (days) a sheet has until they are set. */
    public static final int DEFAULT_TERMS = 14;

    /** The floor a sheet has until one is set. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    private final JdbcTemplate jdbc;

    public SettingStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The setting's value, or null when it has none. */
    public String find(String sheetId, String key) {
        List<String> found = jdbc.queryForList(
                "SELECT setting_value FROM sheet_setting WHERE sheet_id = ? AND setting_key = ?", String.class,
                sheetId, key);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The most a clerk may settle a claim's due at, or null for no limit. */
    public BigDecimal clerkLimit(String sheetId) {
        String value = find(sheetId, CLERK_LIMIT);
        return value == null ? null : new BigDecimal(value);
    }

    /** The least a claim's live due may be: the floor set, else 1.00. */
    public BigDecimal floor(String sheetId) {
        String value = find(sheetId, FLOOR);
        return value == null ? DEFAULT_FLOOR : new BigDecimal(value);
    }

    /** The days after its date a claim is due by: the terms set, else 14. */
    public int terms(String sheetId) {
        String value = find(sheetId, TERMS);
        return value == null ? DEFAULT_TERMS : Integer.parseInt(value);
    }

    public void set(String sheetId, String key, String value) {
        jdbc.update("MERGE INTO sheet_setting (sheet_id, setting_key, setting_value) KEY (sheet_id, setting_key) "
                + "VALUES (?, ?, ?)", sheetId, key, value);
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.util.regex.Pattern;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSetting {
    /** 0.00 or more, with up to two decimals. */
    private static final Pattern LIMIT = Pattern.compile("\\d+(\\.\\d{1,2})?");
    /** A whole number of days, 0 or more. */
    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");

    public void validate(@RequestBody SettingRequest request, Out<SettingInput> body) throws InvalidSheetException {
        String key = request == null || request.key() == null ? "" : request.key().trim();
        boolean floor = SettingStore.FLOOR.equals(key);
        boolean terms = SettingStore.TERMS.equals(key);
        if (!SettingStore.CLERK_LIMIT.equals(key) && !floor && !terms) {
            throw new InvalidSheetException("Not a setting: " + key);
        }
        String value = request.value() == null ? "" : request.value().trim();
        if (terms) {
            if (value.isEmpty()) {
                body.set(new SettingInput(key, String.valueOf(SettingStore.DEFAULT_TERMS), request.user()));
                return;
            }
            if (!DAYS.matcher(value).matches()) {
                throw new InvalidSheetException("The terms must be a whole number of days, 0 or more");
            }
            body.set(new SettingInput(key, String.valueOf(Integer.parseInt(value)), request.user()));
            return;
        }
        if (value.isEmpty() && floor) {
            body.set(new SettingInput(key, SettingStore.DEFAULT_FLOOR.toPlainString(), request.user()));
            return;
        }
        if (value.isEmpty()) {
            body.set(new SettingInput(key, null, request.user()));
            return;
        }
        if (!LIMIT.matcher(value).matches()) {
            throw new InvalidSheetException(floor ? "The floor must be 0.00 or more with up to two decimals"
                    : "The clerk limit must be 0.00 or more with up to two decimals, or blank");
        }
        body.set(new SettingInput(key, new BigDecimal(value).setScale(2).toPlainString(), request.user()));
    }
}
package net.officefloor.hq.app.rollup;

import java.util.Map;

/** The sheet's figures at one moment: each person's claimed and due-total (by person id, in the order
 *  they were added) and the sheet's claimed-total and due-total, all as shown (two decimals, n/a). */
public record Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal) {

    /** A person's figures; {@code name} is what the ROLLUP line shows, not part of the comparison. */
    public record Figures(String name, String claimed, String dueTotal) {
        boolean sameAs(Figures other) {
            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal);
        }
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimFigure;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.ClaimStore;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rate.RateStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.SheetStore;
import org.springframework.stereotype.Service;

/**
 * Works out the sheet's figures as the screen shows them, and records in the audit file how a change
 * moved them: ROLLUP sheet=<id> by=<user> person=<name> claimed=<0.00> due-total=<0.00 or n/a> for each
 * person whose figures changed (a person new to the sheet counts as changed), in the order they were
 * added, then TOTALS sheet=<id> by=<user> claimed-total=<0.00> due-total=<0.00> when the sheet's totals
 * changed. A change that moves no figure records nothing here.
 */
@Service
public class RollupService {

    private static final String NA = "n/a";

    private final PersonStore people;
    private final ClaimStore claims;
    private final RateStore rates;
    private final SheetStore sheets;
    private final SettingStore settings;
    private final Audit audit;

    public RollupService(PersonStore people, ClaimStore claims, RateStore rates, SheetStore sheets, SettingStore settings,
            Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.settings = settings;
        this.audit = audit;
    }

    /** The sheet's figures as the store holds them now. */
    public Rollup snapshot(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        List<Claim> all = claims.list(sheetId);
        BigDecimal floor = settings.floor(sheetId);
        Map<Long, Rollup.Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
        for (Person person : people.list(sheetId)) {
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            boolean fixed = false;
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId()
                        || !counts(claim, person)) {
                    continue;
                }
                claimed = claimed.add(claim.getAmount());
                BigDecimal figure = ClaimFigure.of(claim, rates.find(sheetId, person.getGrade(), claim.getDate()), floor);
                if (figure != null) {
                    due = due.add(figure);
                }
                fixed |= claim.getSettledDue() != null || (claim.isStated() && claim.getStatedDue() != null);
            }
            boolean na = rates.find(sheetId, person.getGrade(), today) == null && !fixed;
            claimedTotal = claimedTotal.add(claimed);
            if (!na) {
                dueTotal = dueTotal.add(due);
            }
            figures.put(person.getId(), new Rollup.Figures(person.getName(), shown(claimed), na ? NA : shown(due)));
        }
        return new Rollup(figures, shown(claimedTotal), shown(dueTotal));
    }

    /** The due-total of the claims that count dated from..to (inclusive): the sum of their figures,
     *  skipping n/a, as the screen shows a period's due-total. */
    public BigDecimal dueBetween(String sheetId, LocalDate from, LocalDate to) {
        List<Claim> all = claims.list(sheetId);
        BigDecimal floor = settings.floor(sheetId);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Person person : people.list(sheetId)) {
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId()
                        || !counts(claim, person)
                        || claim.getDate().isBefore(from) || claim.getDate().isAfter(to)) {
                    continue;
                }
                BigDecimal figure = ClaimFigure.of(claim, rates.find(sheetId, person.getGrade(), claim.getDate()), floor);
                if (figure != null) {
                    total = total.add(figure);
                }
            }
        }
        return total;
    }

    /** Records how the sheet's figures moved since {@code before}, the change made by {@code user}. */
    public void record(String sheetId, String user, Rollup before) {
        Rollup after = snapshot(sheetId);
        String who = " sheet=" + sheetId + " by=" + user;
        after.people().forEach((id, now) -> {
            if (!now.sameAs(before.people().get(id))) {
                audit.record("ROLLUP" + who + " person=" + now.name() + " claimed=" + now.claimed() + " due-total="
                        + now.dueTotal());
            }
        });
        if (!after.claimedTotal().equals(before.claimedTotal()) || !after.dueTotal().equals(before.dueTotal())) {
            audit.record("TOTALS" + who + " claimed-total=" + after.claimedTotal() + " due-total=" + after.dueTotal());
        }
    }

    /** Only OPEN and SETTLED claims count, and a held person's OPEN claims do not. */
    private static boolean counts(Claim claim, Person person) {
        return claim.getStatus() == ClaimStatus.SETTLED
                || (claim.getStatus() == ClaimStatus.OPEN && !person.isHeld());
    }

    private static String shown(BigDecimal value) {
        return value.setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Takes the sheet's figures before a change, so its audit step can record how the change moved them. */
public class SnapshotRollup {
    public void snapshot(@PathVariable("sheetId") String sheetId, RollupService rollups, Out<Rollup> before) {
        before.set(rollups.snapshot(sheetId.trim()));
    }
}
# POST /api/sheets/{sheetId}/settings — change a setting (body: {key, value, user}). The keys are
# clerk-limit: a number of 0.00 or more with up to two decimals, or blank for no limit; and floor: the
# least a claim's live due may be, 0.00 or more with up to two decimals, blank for its default 1.00; and
# terms: the whole days (0 or more) after its date a claim is due by, blank for its default 14.
# Any other key or value is refused (400) and nothing is stored. A stored change is recorded in the
# audit file as SETTING_CHANGED (even when the value is the one already in force), then ROLLUP/TOTALS
# for the figures it moved; a refused one records nothing.
validate:
  class: net.officefloor.hq.app.setting.ValidateSetting
  next: snapshot
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.setting.SaveSetting
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.setting.AuditSettingChanged
  govern: [ transaction ]
